testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { parsearUpload } from './solution.mjs';

test('separa campos e arquivos da encomenda', () => {
  const resultado = parsearUpload(['campo:nome=Ana', 'campo:email=ana@loja.com', 'arquivo:foto.jpg=1024'], 5000);
  assert.deepEqual(resultado, {
    campos: { nome: 'Ana', email: 'ana@loja.com' },
    arquivos: [{ nome: 'foto.jpg', bytes: 1024 }],
  });
});

test('arquivo acima do limite recusa a encomenda inteira', () => {
  assert.throws(() => parsearUpload(['arquivo:video.mp4=6000'], 5000), /excede o limite/);
  assert.throws(() => parsearUpload(['campo:nome=Ana', 'arquivo:foto.jpg=99999'], 100), /excede o limite/);
});

test('campo sem valor é encomenda malformada', () => {
  assert.throws(() => parsearUpload(['campo:nome'], 5000), /sem valor/);
});

test('parte desconhecida é recusada e encomenda vazia devolve tudo vazio', () => {
  assert.throws(() => parsearUpload(['anexo:bilhete.txt'], 5000), /inválida/);
  assert.deepEqual(parsearUpload([], 5000), { campos: {}, arquivos: [] });
});

solutionCode:
export function parsearUpload(partes, limiteBytes) {
  const campos = {};
  const arquivos = [];

  for (const parte of partes) {
    if (parte.startsWith('campo:')) {
      const conteudo = parte.slice('campo:'.length);
      const separador = conteudo.indexOf('=');
      if (separador === -1) {
        throw new Error('campo sem valor');
      }
      campos[conteudo.slice(0, separador)] = conteudo.slice(separador + 1);
    } else if (parte.startsWith('arquivo:')) {
      const conteudo = parte.slice('arquivo:'.length);
      const separador = conteudo.indexOf('=');
      const nome = separador === -1 ? conteudo : conteudo.slice(0, separador);
      const bytes = Number(separador === -1 ? 0 : conteudo.slice(separador + 1));
      if (bytes > limiteBytes) {
        throw new Error('arquivo excede o limite');
      }
      arquivos.push({ nome, bytes });
    } else {
      throw new Error('parte inválida');
    }
  }

  return { campos, arquivos };
}
